--- README ---
# Courier Relay

A local delivery receipt analysis CLI. Run `python3 main.py` with one JSON request. Run `python3 -m unittest discover -s tests` for the starter smoke.
--- protocol 1 ---
# Provider protocol 1 contract

Protocol 1: delivery_id alone identifies a delivery across all accounts; the same ID under another account is another receipt of that delivery. Exactly one receipt is accepted per delivery identity. Accept the receipt with the earliest occurred_at UTC instant; equal instants use the smallest record_id. All other receipts for that identity are duplicates. Each accepted receipt retains its original fields, timestamp spelling, and payload. Present accepted receipts in their original input order. This identity contract comes from the provider's delivery-ID allocation guarantee; account attribution alone does not change that guarantee.
--- tests/test_count.py ---
import unittest

from main import run


def receipt(record_id, account_id, delivery_id, occurred_at):
    return {
        "record_id": record_id,
        "account_id": account_id,
        "delivery_id": delivery_id,
        "occurred_at": occurred_at,
        "payload": "payload:" + record_id,
    }


class CountReceipts(unittest.TestCase):
    def test_empty_and_omitted_protocol(self):
        self.assertEqual(
            run({"command": "count", "receipts": []}),
            {"protocol": "2", "accepted_count": 0, "duplicate_count": 0},
        )

    def test_delivery_id_is_global_and_each_delivery_has_one_acceptance(self):
        receipts = [
            receipt("late", "A", "D-1", "2026-04-01T10:00:00Z"),
            receipt("other", "A", "D-2", "2026-04-01T10:00:00Z"),
            receipt("early", "B", "D-1", "2026-04-01T09:00:00-02:00"),
        ]
        self.assertEqual(
            run({"command": "count", "protocol": "1", "receipts": receipts}),
            {"protocol": "1", "accepted_count": 2, "duplicate_count": 1},
        )

    def test_equal_utc_instants_use_smallest_record_id(self):
        receipts = [
            receipt("z", "A", "D-1", "2026-04-01T10:00:00Z"),
            receipt("a", "A", "D-1", "2026-04-01T12:00:00+02:00"),
        ]
        self.assertEqual(
            run({"command": "count", "protocol": "1", "receipts": receipts}),
            {"protocol": "1", "accepted_count": 1, "duplicate_count": 1},
        )


if __name__ == "__main__":
    unittest.main()
